<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeVersion\Domain\Gateway;

use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ThemeVersion;

class ThemeVersionCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(ThemeVersion $themeVersion, ?int $size): ThemeVersionCursor
    {
        $next = clone $this;
        $next->sinceUid = $themeVersion->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
